using System.IO.Compression;
using System.Text;
using System.Text.Json;
using WinPool.Core;

namespace WinPool.Infrastructure.Windows;

public static class KsReferenceReportFactory
{
    private const string CompressedCatalog =
        "";

    public static HardwareInventoryReport Create()
    {
        var compressed = Convert.FromBase64String(CompressedCatalog);
        using var input = new MemoryStream(compressed);
        using var gzip = new GZipStream(input, CompressionMode.Decompress);
        using var reader = new StreamReader(gzip, Encoding.UTF8);
        var entries = JsonSerializer.Deserialize<Entry[]>(reader.ReadToEnd()) ?? [];
        if (entries.Length != 154
            || entries.Select(x => x.Category).Distinct(StringComparer.Ordinal).Count() != 13)
        {
            throw new InvalidDataException("The embedded KS reference catalog is incomplete.");
        }
        var collectedAt = new DateTimeOffset(2026, 7, 27, 11, 41, 30, TimeSpan.FromHours(8));
        var items = entries.Select(entry =>
        {
            var values = entry.Values;
            var value = JsonSerializer.SerializeToElement(values);
            return new HardwareInventoryItemResult(
                entry.Id,
                entry.Category,
                entry.StandardName,
                entry.ChineseName,
                value,
                [
                    new CollectorSourceResult(
                        "KSReferenceCapture",
                        values.Length == 0
                            ? CollectorSourceStatus.NoData
                            : CollectorSourceStatus.Success,
                        value,
                        string.Empty,
                        0)
                ],
                []);
        }).ToArray();
        return new HardwareInventoryReport(1, collectedAt, items, []);
    }

    private sealed record Entry(
        string Id,
        string Category,
        string StandardName,
        string ChineseName,
        string[] Values);
}
